"""Bounded projected-concatenation column ordering for character-Trie reuse."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Select a constrained column permutation using exact serialized-row scoring."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and the most recent public row orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize one scalar exactly as the evaluator does for scoring."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return exact common-prefix length using binary-search slicing."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings) -> int:
        """Compute ideal character-Trie reuse from sorted adjacent row strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(
                previous, current
            )
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified labels to all source positions with that label."""
        result = {}
        for index, column in enumerate(columns):
            result.setdefault(str(column), []).append(index)
        return result

    @classmethod
    def _blocks(cls, width, columns, requested):
        """Build transitive mandatory column blocks from merge constraints."""
        parent = list(range(width))

        def find(value):
            while parent[value] != value:
                parent[value] = parent[parent[value]]
                value = parent[value]
            return value

        positions = cls._positions(columns)
        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for index in range(width):
            groups.setdefault(find(index), []).append(index)
        return sorted(
            (sorted(group) for group in groups.values()),
            key=lambda group: group[0],
        )

    @classmethod
    def _repair(cls, width, preference, columns, dependencies, blocks):
        """Topologically repair a preference while preserving required blocks."""
        positions = cls._positions(columns)
        edges = []
        seen = set()

        def add(left, right):
            if left != right and (left, right) not in seen:
                seen.add((left, right))
                edges.append((left, right))

        for pair in dependencies or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                add(left[0], right[0])

        for block in blocks:
            for left, right in zip(block, block[1:]):
                add(left, right)

        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for left, right in edges:
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {value: index for index, value in enumerate(preference)}
        queue = [
            (rank.get(index, width + index), index)
            for index in range(width)
            if indegree[index] == 0
        ]
        heapq.heapify(queue)

        answer = []
        while queue:
            _, node = heapq.heappop(queue)
            answer.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(queue, (rank.get(nxt, width + nxt), nxt))

        return answer if len(answer) == width else list(preference)

    @staticmethod
    def _stats(text):
        """Compute length-weighted whole-value repetition statistics per column."""
        rows, width = text.shape
        result = []
        for col in range(width):
            counts = {}
            for value in text[:, col]:
                counts[value] = counts.get(value, 0) + 1
            pair = repeat = mass = 0
            for value, count in counts.items():
                length = len(value)
                pair += length * count * (count - 1)
                repeat += length * max(0, count - 1)
                mass += length * count
            result.append((pair, repeat, mass))
        return result

    @staticmethod
    def _serialize(text, order):
        """Serialize every source row under one complete column permutation."""
        return [
            "".join(text[row, col] for col in order)
            for row in range(text.shape[0])
        ]

    @classmethod
    def _directed_orders(cls, text, stats, blocks):
        """Build two block orders from bounded directed projected concatenations.

        Each ordered pair among at most eighteen active blocks is scored on its
        actual two-block row projection.  Pair gains are then assembled into
        non-cyclic directed chains using a global best-edge pass.
        """
        if len(blocks) <= 1:
            return [sum(blocks, [])]

        rows = text.shape[0]
        mass = [
            sum(stats[col][0] for col in block)
            for block in blocks
        ]
        active = sorted(
            range(len(blocks)),
            key=lambda i: (-mass[i], blocks[i][0]),
        )[:18]

        projected = {}
        singleton_score = {}
        for i in active:
            values = [
                "".join(text[row, col] for col in blocks[i])
                for row in range(rows)
            ]
            projected[i] = values
            singleton_score[i] = cls._score(values)

        gains = []
        for left in active:
            for right in active:
                if left == right:
                    continue
                values = [
                    projected[left][row] + projected[right][row]
                    for row in range(rows)
                ]
                gain = (
                    cls._score(values)
                    - singleton_score[left]
                    - singleton_score[right]
                )
                gains.append((gain, left, right))

        # Prefer strong gains, then deterministic block order.  Select edges
        # with at most one predecessor and successor and reject cycles.
        gains.sort(key=lambda item: (-item[0], item[1], item[2]))
        successor = {}
        predecessor = {}

        def creates_cycle(left, right):
            """Check whether adding left->right closes an existing chain."""
            node = right
            while node in successor:
                node = successor[node]
                if node == left:
                    return True
            return False

        for gain, left, right in gains:
            if gain <= 0:
                continue
            if left in successor or right in predecessor:
                continue
            if creates_cycle(left, right):
                continue
            successor[left] = right
            predecessor[right] = left

        chains = []
        unused = set(active)
        starts = sorted(
            (node for node in active if node not in predecessor),
            key=lambda node: (node, ),
        )
        for start in starts:
            chain = []
            node = start
            while node in unused:
                chain.append(node)
                unused.remove(node)
                if node not in successor:
                    break
                node = successor[node]
            if chain:
                chains.append(chain)

        for node in sorted(unused):
            chains.append([node])

        chains.sort(key=lambda chain: (-len(chain), chain[0]))
        primary = [node for chain in chains for node in chain]

        # A second deterministic candidate reverses chain ranking only; it
        # remains based on the same measured directed edges.
        secondary = [
            node
            for chain in sorted(chains, key=lambda c: (c[0], -len(c)))
            for node in chain
        ]

        inactive = sorted(
            (i for i in range(len(blocks)) if i not in active),
            key=lambda i: (-mass[i], blocks[i][0]),
        )

        answers = []
        seen = set()
        for sequence in (primary, secondary):
            flat = tuple(
                col
                for index in sequence + inactive
                for col in blocks[index]
            )
            if flat not in seen:
                seen.add(flat)
                answers.append(list(flat))
        return answers or [sum(blocks, [])]

    @staticmethod
    def _materialize(df, source, order, serialized):
        """Sort rows by serialized text and copy each original cell unchanged."""
        row_order = sorted(
            range(len(serialized)),
            key=lambda row: (serialized[row], row),
        )
        values = np.empty(source.shape, dtype=object)
        public_orders = []
        for output_row, source_row in enumerate(row_order):
            values[output_row, :] = [
                source[source_row, col] for col in order
            ]
            public_orders.append([df.columns[col] for col in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Return a valid row-sorted, constrained column-permuted DataFrame."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)
        for col in range(width):
            text[:, col] = [
                self._cell_string(value) for value in source[:, col]
            ]

        columns = list(df.columns)
        stats = self._stats(text)
        blocks = self._blocks(width, columns, col_merge)

        baseline = [
            col
            for col, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0],
                    -item[1][1],
                    -item[1][2],
                    item[0],
                ),
            )
        ]

        preferences = [baseline]
        preferences.extend(self._directed_orders(text, stats, blocks))

        best_score = -1
        best_order = None
        best_serialized = None
        for preference in preferences[:3]:
            order = self._repair(
                width,
                preference,
                columns,
                one_way_dep,
                blocks,
            )
            serialized = self._serialize(text, order)
            score = self._score(serialized)
            if score > best_score:
                best_score = score
                best_order = order
                best_serialized = serialized

        result, public_orders = self._materialize(
            df, source, best_order, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

